import pandas as pd

def clean(df):
    df = df.copy()
    if df['body_mass_g'].dtype == 'object':
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    if 'sex' in df.columns:
        df['sex'] = df['sex'].replace({'FEMALE': 'female'})
    if 'flipper_length_mm' in df.columns:
        if df['flipper_length_mm'].dtype == 'object':
            df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    return df

def answer(df):
    result = df.groupby('species')['body_mass_g'].mean().to_dict()
    return result
